// Offline PostgreSQL test for the agency_safety_fda_press_recalls source_url packet (press_recalls.update_sql), pglite.
// The SQL is generated by the Python module from synthetic table rows, then run against synthetic corpus rows.
//   node --test scripts/enrichment/fda_warning_letters/fda-press-recall-urls.test.mjs
import test from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const runtime =
  process.env.PUBLISHER_CODE_PGLITE ??
  path.resolve(
    "private/tools/publisher-code-contract-tests/node_modules/@electric-sql/pglite/dist/index.js",
  );
const { PGlite } = await import(pathToFileURL(runtime).href);

const PAGE = "https://www.fda.gov/safety/recalls-market-withdrawals-safety-alerts/";
// table rows: [path slug, date, company, brands, description]
const TABLE = [
  ["kaytee-recall", "2023-03-20", "Kaytee Products Inc.", "Kaytee", "Wild Bird Food Birders’ Blend"],
  ["obrien-recall", "2024-01-02", "O'Brien Foods", "O'Brien", "Corn  chips"],
  ["twin-a", "2024-02-02", "Twin Co", "Twin", "Snack"],
  ["twin-b", "2024-02-02", "Twin Co", "Twin", "Snack"],
  ["dup-sample", "2024-03-03", "Dup Co", "Dup", "Cake"],
];
const py = `
import json, sys
sys.path.insert(0, "scripts/enrichment/fda_warning_letters")
import press_recalls as pr
rows = [{"path": pr.PAGE_PREFIX + s, "url": pr.wp.FDA + pr.PAGE_PREFIX + s, "date": d, "company_name": c, "brand_names": b,
         "product_description": p} for s, d, c, b, p in json.loads(sys.stdin.buffer.read().decode("utf-8"))]
scope = {"complete": False, "rows_read": len(rows), "totals_reported": [len(rows), len(rows) + 2], "read_on": "2026-10-27"}
sys.stdout.buffer.write(pr.update_sql(pr.unique_table_rows(rows), pr.rule_for(scope)).encode("utf-8"))
`;

function generate() {
  for (const [cmd, args] of [[process.env.PYTHON, []], ["python3", []], ["python", []], ["py", ["-3"]]]) {
    if (!cmd) continue;
    const r = spawnSync(cmd, [...args, "-B", "-c", py], { input: JSON.stringify(TABLE), encoding: "utf8" });
    if (!r.error && r.status === 0) return r.stdout;
  }
  throw new Error("Python 3 is required to generate the packet");
}

const CORPUS = `
create table public.corpus_datasets (id text primary key, label text not null, ready boolean not null default false,
  metadata jsonb not null default '{}');
create table public.corpus_records (dataset text not null references public.corpus_datasets(id), id text not null,
  category text not null, title text not null default '', source_url text, ordinal bigint not null default 0,
  item jsonb not null, detail jsonb not null default '{}', primary key (dataset, id));
insert into public.corpus_datasets (id, label) values ('agency_safety_fda_press_recalls', 'x');
`;
// corpus rows: [id, listed_date, company, brands, description, source_url]
const ROWS = [
  ["fda-press:a", "2023-03-20", "Kaytee Products Inc.", "Kaytee", "Wild Bird Food Birders’ Blend", ""],
  ["fda-press:b", "2024-01-02", "O'Brien Foods ", "O'Brien", "Corn chips", null], // whitespace differs only
  ["fda-press:c", "2024-02-02", "Twin Co", "Twin", "Snack", ""], // key twice in FDA's table
  ["fda-press:d", "2024-03-03", "Dup Co", "Dup", "Cake", ""], // key twice in the dataset
  ["fda-press:e", "2024-03-03", "Dup Co", "Dup", "Cake", ""],
  ["fda-press:f", "2023-03-20", "Kaytee Products", "Kaytee", "Wild Bird Food Birders’ Blend", ""], // name differs
];

test("press-recall packet: exact unique keys only, idempotent", async () => {
  const sql = generate();
  const db = new PGlite();
  await db.exec(CORPUS);
  for (const [id, listed_date, company_name, brand_names, product_description, source_url] of ROWS)
    await db.query(
      "insert into public.corpus_records (dataset, id, category, source_url, item, detail) values ('agency_safety_fda_press_recalls', $1, 'agency_safety', $2, '{}', $3)",
      [id, source_url, { fields: { listed_date, company_name, brand_names, product_description } }],
    );
  await db.exec(sql);
  await db.exec(sql);
  const got = Object.fromEntries(
    (await db.query("select id, coalesce(source_url, '') as u from public.corpus_records order by id")).rows.map((r) => [r.id, r.u]),
  );
  assert.deepEqual(got, {
    "fda-press:a": PAGE + "kaytee-recall",
    "fda-press:b": PAGE + "obrien-recall",
    "fda-press:c": "",
    "fda-press:d": "",
    "fda-press:e": "",
    "fda-press:f": "",
  });
  const rule = (await db.query("select metadata->>'source_url_rule' as r from public.corpus_datasets")).rows[0].r;
  // the read reported two totals, so the rule claims uniqueness only among the rows read, never in FDA's whole table
  assert.match(rule, /unique in this dataset and among the \d+ FDA table rows read on 2026-10-27/);
  assert.doesNotMatch(rule, /in FDA's table \(all/);
});
